#include "dk1/ppu_bg_renderer.h"
static uint16_t word(const Dk1VramImage*v,size_t wa){size_t b=(wa&0x7FFFu)*2u;return (uint16_t)v->bytes[b]|((uint16_t)v->bytes[(b+1u)&0xFFFFu]<<8u);}
static size_t mapaddr(const Dk1PpuBgLayout*l,size_t x,size_t y){size_t sx=x/32u,sy=y/32u,ix=x%32u,iy=y%32u,screen;if(l->tilemap_width==64u&&l->tilemap_height==64u)screen=sy*2u+sx;else if(l->tilemap_width==64u)screen=sx;else if(l->tilemap_height==64u)screen=sy;else screen=0;return l->screen_base_word+screen*0x400u+iy*32u+ix;}
bool dk1_ppu_render_vram_bg(const Dk1VramImage*v,const Dk1CgramImage*c,const Dk1PpuBgLayout*l,uint16_t sx,uint16_t sy,Dk1RgbaSurface s,bool tz){Dk1Rgba8 pal[256];size_t py,px,tbytes;if(!v||!c||!l||!s.pixels||!l->bits_per_pixel)return false;dk1_cgram_decode_rgba(c,pal);tbytes=l->bits_per_pixel*8u;for(py=0;py<s.height;py++)for(px=0;px<s.width;px++){size_t wx=(sx+px)%(l->tilemap_width*8u),wy=(sy+py)%(l->tilemap_height*8u),tx=wx/8u,ty=wy/8u;uint16_t tw=word(v,mapaddr(l,tx,ty));uint16_t id=tw&0x3FFu;bool hf=(tw&0x4000u)!=0,vf=(tw&0x8000u)!=0;size_t ix=hf?7u-(wx&7u):(wx&7u),iy=vf?7u-(wy&7u):(wy&7u);size_t base=((size_t)l->character_base_word*2u+(size_t)id*tbytes)&0xFFFFu;uint8_t raw[64]={0},pix[64]={0},pidx;size_t i;for(i=0;i<tbytes;i++)raw[i]=v->bytes[(base+i)&0xFFFFu];if(l->bits_per_pixel==2)dk1_snes_decode_2bpp_tile(raw,pix);else if(l->bits_per_pixel==4)dk1_snes_decode_4bpp_tile(raw,pix);else dk1_snes_decode_8bpp_tile(raw,pix);pidx=pix[iy*8u+ix];if(tz&&pidx==0){s.pixels[py*s.stride+px].a=0;continue;}if(l->bits_per_pixel==2)pidx=(uint8_t)(((tw>>10u)&7u)*4u+pidx);else if(l->bits_per_pixel==4)pidx=(uint8_t)(((tw>>10u)&7u)*16u+pidx);s.pixels[py*s.stride+px]=pal[pidx];}return true;}
